// The main app's unchanged GPU question-bar shader and composition graph.
export const questionRect=(width,height,focus=0)=>{const w=Math.max(460,Math.min(720,width*.44))+focus*40;return {x:(width-w)/2,y:height-88,width:w,height:58};};
